#include <iostream>
using namespace std;

int main() {
    long long n;
    int r;
    if (!(cin >> n >> r)) return 0;

    if (n == 0) { cout << "0\n"; return 0; }

    int st[64], top = -1;
    while (n > 0) {
        st[++top] = (int)(n % r);   // 余数入栈
        n /= r;
    }
    const char *digits = "0123456789ABCDEF";
    while (top >= 0) {
        cout << digits[st[top--]];  // 倒序出栈
    }
    cout << "\n";
    return 0;
}
